(()=>{
const vuePage=Vue.ref('');
Vue.createApp({setup(){return{page:vuePage}},template:'<div id="app-content" v-html="page"></div>'}).mount('#app');
const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)],db=SF.store,brand=SF.config;
const equipmentPhotos=['photo-1534438327276-14e5300c3a48','photo-1583454110551-21f2fa2afe61','photo-1517836357463-d25dfeac3438','photo-1571902943202-507ec2618e8f','photo-1538805060514-97d9cc17730c','photo-1518611012118-696072aa579a','photo-1581009146145-b5ef050c2e1e','photo-1593079831268-3381b0db4a77','photo-1593079831268-3381b0db4a77','photo-1534367610401-9f5ed68180aa','photo-1579758629938-03607ccdbaba','photo-1580261450046-d0a30080dc9b'];
const params=new URLSearchParams(location.search),view=params.get('view')||'home',formatMoney=n=>'₹'+Number(n).toLocaleString('en-IN'),prettyDate=d=>d?new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—',planFor=s=>db.plan(s.Plan_ID),toast=(m)=>{const el=document.createElement('div');el.className='toast';el.textContent=m;$('#toast-region').append(el);setTimeout(()=>el.remove(),4200)},route=(p,query='')=>`index.html?view=${encodeURIComponent(p)}${query}`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),activeUser=db.session(),member=activeUser?.memberId?db.member(activeUser.memberId):null;
const publicNav=[['Home','home'],['About','about'],['Plans','plans'],['Find My Plan','finder'],['Trainers','trainers'],['Equipment','equipment'],['Schedule','schedule'],['Help Desk','help']];
const finderDefaults=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}');finderDefaults.budget=finderDefaults.budget||2500;finderDefaults.commit=finderDefaults.commit||3;localStorage.setItem('sf-finder-draft',JSON.stringify(finderDefaults));
function header(){return `<header class="site-header"><div class="wrap nav"><a class="brand" href="${route('home')}"><span class="brand-mark">S</span>${brand.brand}</a><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Open navigation"><i class="icon-menu" aria-hidden="true"></i></button><nav class="navlinks">${publicNav.map(([n,p])=>`<a href="${route(p)}" ${p===view?'aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="nav-actions">${activeUser?`<a class="small muted hide-mobile" href="${route(activeUser.role==='admin'?'admin-dashboard':'member-dashboard')}">${esc(activeUser.user)}</a><button class="btn secondary hide-mobile" data-action="signout">Sign Out</button>`:`<a class="btn secondary hide-mobile" href="${route('signin')}">Sign In</a><a class="btn" href="${route('signup')}">Join Now</a>`}</div></div></header>`}
const footer=()=>`<footer><div class="wrap"><div class="footer-grid"><div><a class="brand" href="${route('home')}"><span class="brand-mark">S</span>${brand.brand}</a><p class="muted">${brand.slogan}</p><div class="small muted">${brand.address}<br>${brand.phone}<br>${brand.email}</div></div><div><h4>Explore</h4><div class="footer-links">${publicNav.slice(1,6).map(([n,p])=>`<a href="${route(p)}">${n}</a>`).join('')}</div></div><div><h4>Membership</h4><div class="footer-links"><a href="${route('plans')}">Plans & pricing</a><a href="${route('finder')}">Find my plan</a><a href="${route('privacy')}">Privacy policy</a><a href="${route('terms')}">Terms</a><a href="${route('refund')}">Refund policy</a></div></div><div><h4>Stay in the loop</h4><form class="form" data-form="newsletter"><input class="input" type="email" placeholder="Your email address" required><button class="btn small-btn">Get updates</button></form><p class="small muted">${brand.hours}</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${brand.brand}.</span></div></div></footer>`;
function shell(content){
  vuePage.value=header()+content+footer();
  Vue.nextTick(()=>{
    if(view==='equipment')$$('.equipment-card').forEach((card,i)=>{
      const fallback='https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1000&q=82';
      const url=`https://images.unsplash.com/${equipmentPhotos[i%equipmentPhotos.length]}?auto=format&fit=crop&w=1000&q=82`;
      card.style.setProperty('--equip-photo',`url("${url}")`);
      const probe=new Image();
      probe.onerror=()=>card.style.setProperty('--equip-photo',`url("${fallback}")`);
      probe.src=url;
    });
  });
}const hero=(title,desc,extraClass='')=>`<section class="page-hero ${extraClass}"><div class="wrap"><div class="crumb"><a href="${route('home')}">Home</a> / ${title}</div><div class="eyebrow">${brand.brand}</div><h1 class="heading">${title}</h1><p class="muted">${desc}</p></div></section>`;
function plansGrid(filter=null){let plans=db.all().plans;if(filter)plans=plans.filter(p=>p.Duration_Months===filter);return `<div class="grid three">${plans.map(p=>{const apex=p.Plan_Name.startsWith('Apex');const baseline=apex?3000:1500;return `<article class="card"><span class="tag ${apex?'hot':''}">${apex?'APEX':'FORGE'} · ${p.Duration_Months} ${p.Duration_Months===1?'MONTH':'MONTHS'}</span><h3>${p.Plan_Name}</h3><div class="plan-price">${formatMoney(p.Fee)} <small>/ upfront</small></div><p>${formatMoney(Math.round(p.Fee/p.Duration_Months))} per month · Save ${Math.max(0,Math.round((baseline-p.Fee/p.Duration_Months)*100/baseline))}% vs monthly</p><ul class="line-list">${(apex?brand.apex:brand.forge).map(x=>`<li>${x}</li>`).join('')}</ul><a class="btn" href="${route('purchase',`&plan=${p.Plan_ID}`)}">Choose plan</a></article>`}).join('')}</div>`}
function homeSchedule(){const sessions=db.all().sessions.slice(0,3),trainers=db.all().trainers;return `<section class="home-schedule"><div class="wrap home-schedule-layout ring-1 ring-white/10 shadow-2xl transition-all duration-500"><div class="home-schedule-photo"><div class="eyebrow">Show up. Put in the work.</div><p>Good sessions<br><strong>start here.</strong></p><a class="btn" href="${route('schedule')}">View the schedule →</a></div><div class="home-schedule-panel"><div class="eyebrow">Next on the floor</div><h2 class="heading">Make time to train.</h2><p class="muted">A quick look at the next sessions. Find your focus and book your place.</p><div class="home-session-list">${sessions.map(s=>{const trainer=trainers.find(t=>t.Trainer_ID===s.Trainer_ID);const date=new Date(s.Slot_DateTime);return `<div class="home-session"><div class="session-time"><strong>${date.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</strong><span>${date.toLocaleDateString('en-IN',{weekday:'short',day:'2-digit',month:'short'})}</span></div><div><h3>${esc(s.Focus_Area)}</h3><p>${esc(trainer?.Name||'Sinewforge coach')}</p></div><span class="session-arrow" aria-hidden="true">↗</span></div>`}).join('')}</div><a class="small home-schedule-link" href="${route(activeUser?'member-sessions':'signin')}">Book a session →</a></div></div></section>`}
function home(){return `<main><section class="hero relative overflow-hidden"><div class="wrap hero-content"><div class="eyebrow">Built daily. Earned always.</div><h1 class="display font-extrabold tracking-tight">Forge Strength.<br>Own Every Rep.</h1><p>Focused coaching, dependable equipment and room to make training part of your week.</p><div class="hero-actions"><a class="btn" href="${route('finder')}">Find My Plan <span>→</span></a><a class="btn secondary" href="${route('signup')}">Join Now</a></div><div class="hero-stats"><div class="stat"><strong>8</strong><span>Plans to choose from</span></div><div class="stat"><strong>6</strong><span>Coaches in the directory</span></div><div class="stat"><strong>24</strong><span>Equipment listings</span></div><div class="stat"><strong>14</strong><span>Days in the session schedule</span></div></div></div></section><div class="marquee"><div class="marquee-track">${Array.from({length:2},()=>`<span>FIND YOUR TRAINING PLAN <b>◆</b></span><span>SESSIONS THROUGH THE WEEK <b>◆</b></span><span>YEARLY PLANS SAVE UP TO 33 PERCENT <b>◆</b></span><span>COACHES WITH A PLAN <b>◆</b></span><span>FORGE STRENGTH. OWN EVERY REP. <b>◆</b></span><span>EVERY REP COUNTS <b>◆</b></span>`).join('')}</div></div><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Train with intent</div><h2 class="heading">Build your kind of strong</h2></div><p class="muted">Build a steady routine across strength, conditioning, group training and recovery.</p></div><div class="grid three">${[['Strength floor','Progressive strength training with room to grow.','https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?auto=format&fit=crop&w=900&q=80'],['Conditioning zone','Build endurance on equipment that keeps up.','https://images.unsplash.com/photo-1538805060514-97d9cc17730c?auto=format&fit=crop&w=900&q=80'],['Recovery studio','Move well, recover smart, come back ready.','https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=900&q=80']].map(x=>`<article class="card"><img class="card-image" src="${x[2]}" alt="${x[0]} at Sinewforge Fitness"><h3>${x[0]}</h3><p>${x[1]}</p><a class="small" href="${route('equipment')}">Explore the facility →</a></article>`).join('')}</div></div></section>${homeSchedule()}<section class="band"><div class="wrap grid two" style="align-items:center"><div><div class="eyebrow">Find your starting point</div><h2 class="heading">Your stronger self starts here.</h2><p class="muted">Tell us how you like to train, what you want to achieve and what works for your budget. We’ll match you with a plan.</p><a class="btn" href="${route('finder')}">Take the quick plan finder →</a></div><div class="card"><div class="eyebrow">Training that fits real life</div><h3>Progress, at your pace</h3><p>Pick monthly flexibility or save with a longer commitment. See the full price before you decide.</p><a class="small" href="${route('plans')}">Compare all 8 plans →</a></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Straightforward memberships</div><h2 class="heading">A plan that moves with you</h2></div><a class="btn secondary" href="${route('plans')}">See all plans →</a></div>${plansGrid(3)}</div></section><section class="section" style="padding-top:0"><div class="wrap"><div class="card" style="background:linear-gradient(100deg,#1e232b,#252a31)"><div class="eyebrow">Built daily. Earned always.</div><p class="quote">“Train hard. Recover smart. Come back ready.”</p><div class="small muted">THE SINEWFORGE STANDARD</div></div></div></section><section class="band"><div class="wrap section-head" style="margin:0"><div><div class="eyebrow">Ready when you are</div><h2 class="heading">Every rep counts.</h2></div><a class="btn" href="${route('signup')}">Start your membership →</a></div></section></main>`}
function finder(){const saved=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}'),step=Number(saved.step||0);const groups=[['What kind of training calls to you?',['Weight Training','Cardio and HIIT','CrossFit and Functional','Yoga and Flexibility','Dance Fitness','Personal Training','Weight Loss Program']],['What would you like to use?',['Strength Machines','Free Weights','Cardio Machines','Functional Training Area','Recovery Zone','Group Classes','Bodyweight Only']],['What is your main goal?',['Lose Weight','Build Muscle','Gain Strength','Improve Stamina','Stay Fit','Flexibility and Recovery']]];let content;if(step<3){const [q,opts]=groups[step];const arr=saved[['training','equipment','goal'][step]]||[];content=`<h2 class="heading">${q}</h2><p class="muted">${step===1?'Choose all that sound right.':''}</p><div class="choice-grid">${opts.map(o=>`<button class="choice ${arr.includes(o)?'selected':''}" data-choice="${esc(o)}">${esc(o)}</button>`).join('')}</div>`}else{content=`<h2 class="heading">Set your comfort zone</h2><div class="card"><label class="field"><span>Monthly budget <b id="budget-value">${formatMoney(saved.budget||2500)}</b></span><input type="range" min="1000" max="4000" step="100" value="${saved.budget||2500}" data-budget></label><div style="height:20px"></div><label class="field">How long can you commit?<select data-commit>${[[1,'1 month'],[3,'3 months'],[6,'6 months'],[12,'12 months']].map(x=>`<option value="${x[0]}" ${Number(saved.commit||3)===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label></div><div style="height:16px"></div><button class="btn" data-action="recommend">Show my matches →</button>`}shell(`${hero('Find my plan','A few quick choices. A clear recommendation built around your training, goals and budget.')}<section class="section"><div class="wrap finder-shell"><div class="small muted">${step<4?`STEP ${step+1} OF 4`:''}</div><div class="progress"><span style="width:${Math.min(100,(step+1)*25)}%"></span></div>${content}<div class="pill-row" style="margin-top:24px"><button class="btn secondary ${step===0?'hide':''}" data-action="back-step">← Back</button>${step<3?`<button class="btn" data-action="next-step">${step===2?'Continue':'Next'} →</button>`:''}<button class="btn secondary" data-action="retake">Retake</button></div><div id="results" style="margin-top:28px"></div></div></section>`)}
function recommend(){const a=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}');if(!a.training||!a.goal||!(a.equipment||[]).length||!a.commit){toast('Complete each step to see your plan matches.');return}SF.store.addFinder(a);let tier=(a.training==='Personal Training'||a.training==='CrossFit and Functional'||a.equipment.includes('Recovery Zone')||a.goal==='Flexibility and Recovery')?'Apex':'Forge';const horizons={'Lose Weight':3,'Build Muscle':6,'Gain Strength':6,'Improve Stamina':3,'Stay Fit':1,'Flexibility and Recovery':3};const horizon=horizons[a.goal]||3;let plans=db.all().plans.map(p=>({...p,monthly:p.Fee/p.Duration_Months,otherTier:p.Plan_Name.startsWith('Apex')!== (tier==='Apex')}));plans.sort((x,y)=>{const score=p=>[(p.monthly<=a.budget?0:1),(p.Duration_Months>=horizon?0:1),(p.Duration_Months<=a.commit?0:1),p.monthly];const sx=score(x),sy=score(y);for(let i=0;i<sx.length;i++)if(sx[i]!==sy[i])return sx[i]-sy[i];return 0});const fitting=plans.filter(p=>p.monthly<=a.budget),lowest=fitting.reduce((m,p)=>!m||p.monthly<m.monthly?p:m,null);const best=plans.find(p=>p.Plan_Name.startsWith(tier)&&p.Duration_Months>=horizon)||plans[0];const days=Math.max(1,best.Duration_Months*30),savings=(tier==='Apex'?3000:1500)*best.Duration_Months-best.Fee;const nudge=plans.filter(p=>p.Plan_Name.startsWith(tier)&&p.monthly<=a.budget).sort((x,y)=>y.Duration_Months-x.Duration_Months)[0];$('#results').innerHTML=`<div class="eyebrow">Your matches</div><h2 class="heading">A clear path to ${esc(a.goal.toLowerCase())}</h2>${nudge?`<div class="notice">A longer plan brings your monthly cost into budget: choose ${nudge.Plan_Name.replace(tier+' ','')} and pay ${formatMoney(nudge.monthly)} per month.</div>`:''}<div style="height:14px"></div><div class="grid two">${[best,lowest&&lowest.Plan_ID!==best.Plan_ID?lowest:null,plans.find(p=>p.otherTier)].filter(Boolean).filter((p,i,arr)=>arr.findIndex(x=>x.Plan_ID===p.Plan_ID)===i).map(p=>`<article class="card"><div class="pill-row"><span class="tag ${p.Plan_ID===best.Plan_ID?'hot':''}">${p.Plan_ID===best.Plan_ID?'BEST FIT':p.Plan_ID===lowest?.Plan_ID?'BEST VALUE':'OPTIONAL '+(p.Plan_Name.startsWith('Apex')?'UPGRADE':'LOWER COST')}</span>${p.monthly>a.budget?`<span class="tag">OVER BUDGET +${formatMoney(Math.round(p.monthly-a.budget))}/mo</span>`:''}</div><h3>${p.Plan_Name}</h3><p class="plan-price">${formatMoney(p.Fee)} <small>upfront</small></p><p>${formatMoney(Math.round(p.monthly))}/month · ${formatMoney(Math.round(p.Fee/days))}/day · Save ${formatMoney(Math.max(0,savings))} vs monthly</p><p>Why this plan: ${p.Plan_Name.startsWith(tier)?'matches your training tier':'gives you a flexible alternative'} and supports your ${esc(a.goal.toLowerCase())} goal.</p><ul class="line-list">${(p.Plan_Name.startsWith('Apex')?brand.apex:brand.forge).map(z=>`<li>${z}</li>`).join('')}</ul><a class="btn" href="${route('purchase',`&plan=${p.Plan_ID}`)}">Choose this plan</a></article>`).join('')}</div><div class="pill-row" style="margin-top:18px">${[1,3,6,12].map(d=>`<a class="pill ${Number(a.commit)===d?'active':''}" href="#results">${d} months</a>`).join('')}</div>`}
function infoPage(type){const map={about:['About us','A training home built on good coaching, honest progress and a community that shows up.'],trainers:['Meet the trainers','Experienced coaches. Clear cues. Progress you can measure.'],equipment:['Training floor','Purposeful equipment, maintained for the work you came to do.'],schedule:['Class schedule','Find your next session. Book a spot after signing in.'],help:['Help desk','Answers, support and a real person when you need one.'],privacy:['Privacy policy','How Sinewforge Fitness handles member information.'],terms:['Terms and conditions','The simple ground rules for training with us.'],refund:['Membership and refund policy','Clear membership, cancellation and refund terms.']};const [title,desc]=map[type]||['Not found','The page you requested is unavailable.'];let body='';if(type==='about')body=`<div class="grid two"><div class="card"><div class="eyebrow">Our mission</div><h3>Stronger, together.</h3><p>We make excellent coaching and an energizing training floor accessible to people at every stage. Progress is built one good session at a time.</p><ul class="line-list"><li>Coaching that meets you where you are</li><li>Clean, maintained equipment</li><li>Respectful space for every body</li></ul></div><div class="card"><img class="card-image" src="https://images.unsplash.com/photo-1571902943202-507ec2618e8f?auto=format&fit=crop&w=1000&q=80" alt="Bright training floor at the gym"><h3>Room to do the work</h3><p>Strength, conditioning, group classes and recovery under one roof.</p><a class="btn secondary" href="${route('schedule')}">See this week’s schedule</a></div></div><div class="card" style="margin-top:18px"><h3>Visit us</h3><p>${brand.address}<br>${brand.hours}<br>${brand.phone} · ${brand.email}</p></div>`;else if(type==='trainers')body=`<div class="pill-row" style="margin-bottom:20px"><button class="pill active" data-filter="all">All trainers</button>${[...new Set(db.all().trainers.map(t=>t.Specialization))].map(s=>`<button class="pill" data-filter="${esc(s)}">${esc(s)}</button>`).join('')}</div><div class="grid three">${db.all().trainers.map(t=>`<article class="card trainer-card ring-1 ring-white/10 backdrop-blur-xl transition-all duration-300 hover:-translate-y-1 hover:shadow-2xl" data-specialty="${esc(t.Specialization)}"><div class="avatar ring-4 ring-ember/20 shadow-lg">${t.Name.split(' ').map(x=>x[0]).join('')}</div><h3 style="margin-top:16px">${esc(t.Name)}</h3><p>${esc(t.Specialization)}</p><a class="small" href="${route(activeUser?'member-sessions':'signin')}">Book a session →</a></article>`).join('')}</div>`;else if(type==='equipment')body=`<div class="pill-row" style="margin-bottom:20px"><button class="pill active" data-filter="all">All equipment</button>${[...new Set(db.all().equipment.map(e=>e.Category))].map(s=>`<button class="pill" data-filter="${esc(s)}">${esc(s)}</button>`).join('')}</div><div class="grid three">${db.all().equipment.map(e=>`<article class="card equipment-card" data-category="${esc(e.Category)}"><span class="tag ${['Good','Excellent'].includes(e.Condition)?'good':'warn'}">${['Good','Excellent'].includes(e.Condition)?'Available':'Under Service'}</span><h3 style="margin-top:14px">${esc(e.Name)}</h3><p>${esc(e.Category)}</p></article>`).join('')}</div>`;else if(type==='schedule')body=`<div class="pill-row" style="margin-bottom:20px"><select class="input" style="width:auto" data-session-filter><option value="all">All focus areas</option>${[...new Set(db.all().sessions.map(s=>s.Focus_Area))].map(x=>`<option>${x}</option>`).join('')}</select><select class="input" style="width:auto" data-trainer-filter><option value="all">All trainers</option>${db.all().trainers.map(t=>`<option value="${t.Trainer_ID}">${t.Name}</option>`).join('')}</select></div>${sessionsTable()}`;else if(type==='help')body=`<div class="grid two"><div class="card"><h3>Frequently asked</h3>${[['Membership','Choose a plan based on your goals, preferred training and time horizon. Your full price is shown before checkout.'],['Payments','We accept cash at the desk, UPI, cards and net banking. Receipts are saved in your member portal.'],['Sessions','Browse the weekly schedule and book online. You can cancel up to two hours before a session.'],['Equipment','Our team checks equipment daily. Items under service are marked clearly.'],['Account','Use a one-time verification code to sign in. Contact us if you need help updating your details.']].map(([q,a])=>`<details style="border-bottom:1px solid var(--border);padding:14px 0"><summary>${q}</summary><p class="muted">${a}</p></details>`).join('')}</div><form class="card form" data-form="ticket"><h3>Send us a note</h3><div class="field"><label>Name</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field"><label>Category</label><select name="category"><option>Membership</option><option>Payments</option><option>Sessions</option><option>Equipment</option><option>Account</option></select></div><div class="field"><label>Message</label><textarea class="input" name="message" rows="4" required></textarea></div><button class="btn">Send request</button></form></div><div class="card" style="margin-top:18px"><h3>Talk to us</h3><p>${brand.phone} · ${brand.email}<br>${brand.address}<br>${brand.hours}</p></div>`;else body=`<div class="grid two"><aside class="card"><h3>On this page</h3><div class="footer-links">${['Overview','Your responsibilities','Membership and payments','Contact'].map(x=>`<a href="#${x.toLowerCase().replaceAll(' ','-')}">${x}</a>`).join('')}</div><p class="small muted">Last updated 19 Oct 2026</p></aside><article class="card"><h3 id="overview">${title}</h3><p>We collect the information you provide when you create an account, manage a membership or contact our team. This can include your name, date of birth, phone number, email address and membership activity.</p><h3 id="your-responsibilities">How we use information</h3><p>We use account information to provide membership services, process payments, manage bookings, record attendance, answer support requests and keep our facilities safe. We do not sell member data.</p><h3 id="membership-and-payments">Membership and payments</h3><p>Membership fees, plan duration and start/end dates are shown before purchase. Memberships are personal and non-transferable. Cancellation and refund requests are reviewed under our published refund policy. Payment records are linked to the subscription they cover.</p><h3 id="contact">Questions or requests</h3><p>You can ask to review or correct your profile information by contacting ${brand.email} or visiting the front desk at ${brand.address}. We retain records only as needed to provide services and meet applicable obligations.</p></article></div>`;shell(`${hero(title,desc,type==='trainers'?'trainer-hero':'')}<section class="section ${type==='trainers'?'trainers-section':''}"><div class="wrap">${body}</div></section>`)}
function sessionsTable(){return `<div class="table-wrap"><table><thead><tr><th>Session</th><th>Date & time</th><th>Coach</th><th>Action</th></tr></thead><tbody>${db.all().sessions.map(s=>{const t=db.all().trainers.find(x=>x.Trainer_ID===s.Trainer_ID),booked=activeUser?.memberId&&db.all().bookings.some(b=>b.Member_ID===activeUser.memberId&&b.Session_ID===s.Session_ID);return `<tr data-focus="${s.Focus_Area}" data-trainer="${s.Trainer_ID}"><td>${s.Focus_Area}</td><td>${new Date(s.Slot_DateTime).toLocaleString('en-IN',{weekday:'short',day:'2-digit',month:'short',hour:'numeric',minute:'2-digit'})}</td><td>${t?.Name||'Coach'}</td><td>${activeUser?.role==='member'?`<button class="btn small-btn" data-book="${s.Session_ID}" ${booked?'disabled':''}>${booked?'Booked':'Book'}</button>`:`<a class="btn small-btn" href="${route('signin')}">Book</a>`}</td></tr>`}).join('')}</tbody></table></div>`}
function plansPage(){shell(`${hero('Plans & pricing','Pick the tier and duration that fit your training. Your full price is always upfront.')}<section class="section"><div class="wrap"><div class="pill-row" style="margin-bottom:24px">${[[0,'All plans'],[1,'Monthly'],[3,'Quarterly'],[6,'Half Yearly'],[12,'Yearly']].map(([v,l])=>`<button class="pill ${v===0?'active':''}" data-plan-filter="${v}">${l}</button>`).join('')}</div><div id="plan-list">${plansGrid()}</div><div class="card" style="margin-top:28px"><h3>Compare Forge and Apex</h3><div class="table-wrap"><table><thead><tr><th>Included</th><th>Forge</th><th>Apex</th></tr></thead><tbody>${[['Gym floor','Included','Included'],['Cardio & strength zones','Included','Included'],['Group classes','Included','Included'],['Trainer sessions','—','8 per month'],['Recovery zone','—','Included'],['Diet consultation','—','Included']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></div></section>`)}
function authPage(signup=false){if(signup){shell(`${hero('Join Sinewforge','Your next strong habit starts here. Create a member profile and we’ll help you pick a plan.')}<section class="section"><div class="wrap" style="max-width:680px"><form class="card form" data-form="signup"><div class="field-row"><div class="field"><label>Full name</label><input class="input" name="name" required></div><div class="field"><label>Date of birth</label><input class="input" name="dob" type="date" required></div></div><div class="field-row"><div class="field"><label>Gender</label><select name="gender"><option>Prefer not to say</option><option>Male</option><option>Female</option><option>Other</option></select></div><div class="field"><label>Mobile number</label><input class="input" name="phone" inputmode="numeric" pattern="[6-9][0-9]{9}" placeholder="10 digit Indian number" required></div></div><div class="field"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field"><label>Join date</label><input class="input" type="date" value="${new Date().toISOString().slice(0,10)}" readonly></div><label class="small"><input type="checkbox" required> I agree to the <a href="${route('terms')}">membership terms</a>.</label><button class="btn">Create account</button><p class="small muted">Already a member? <a href="${route('signin')}">Sign in</a></p></form></div></section>`);return}shell(`${hero('Welcome back','Sign in securely with a verification code. No password to remember.')}<section class="section"><div class="wrap" style="max-width:520px"><form class="card form" data-form="signin"><div class="pill-row"><button class="pill active" type="button" data-role="member">Member</button><button class="pill" type="button" data-role="admin">Staff or Owner</button><input type="hidden" name="role" value="member"></div><div class="field"><label>Phone, email or member ID</label><input class="input" name="identity" placeholder="you@example.com" required></div><div class="small muted">Demo staff: owner@sinewforge.fit · Demo member: member1@example.com</div><button class="btn">Send verification code</button><div class="hide" data-otp-zone><p class="muted">Enter your six digit code. It expires in five minutes.</p><div class="otp">${Array.from({length:6},(_,i)=>`<input class="input" inputmode="numeric" maxlength="1" aria-label="Code digit ${i+1}" data-otp="${i}">`).join('')}</div><label class="small"><input type="checkbox" name="remember"> Remember this device</label><button class="btn" type="button" data-action="verify-code">Verify & sign in</button><button class="small muted" type="button" data-action="resend">Resend code</button></div><p class="small muted">New here? <a href="${route('signup')}">Create a member account</a></p></form></div></section>`)}
function purchase(){const id=params.get('plan'),p=db.plan(id);if(!p){shell(`${hero('Choose a plan','Select a membership plan to continue.')}<section class="section"><div class="wrap">${plansGrid()}</div></section>`);return}const s=db.activeSubscription(member?.Member_ID),start=new Date(s?s.End_Date:new Date().toISOString().slice(0,10));if(s)start.setDate(start.getDate()+1);const end=new Date(start);end.setMonth(end.getMonth()+p.Duration_Months);shell(`${hero('Review your membership','Confirm your plan details and choose a payment method.')}<section class="section"><div class="wrap" style="max-width:760px"><div class="grid two"><article class="card"><span class="tag hot">${p.Plan_Name.startsWith('Apex')?'APEX':'FORGE'}</span><h2 class="heading">${p.Plan_Name}</h2><p class="plan-price">${formatMoney(p.Fee)}</p><p class="muted">Start ${prettyDate(start.toISOString().slice(0,10))}<br>End ${prettyDate(end.toISOString().slice(0,10))}</p><p>${formatMoney(p.Fee/p.Duration_Months)} / month · ${formatMoney(Math.round(p.Fee/(p.Duration_Months*30)))} / day</p></article><form class="card form" data-form="purchase"><input type="hidden" name="planId" value="${p.Plan_ID}"><h3>Payment method</h3>${['UPI','Card','Net Banking','Cash at desk'].map((x,i)=>`<label class="notice"><input type="radio" name="mode" value="${x==='Cash at desk'?'Cash':x}" ${i===0?'checked':''}> ${x}</label>`).join('')}<button class="btn">Continue to simulated payment · ${formatMoney(p.Fee)}</button><p class="small muted">Demo checkout: no real payment is taken.</p></form></div></div></section>`)}
function receipt(result){const content=`<div class="wrap section"><div class="card" style="max-width:700px;margin:auto" id="receipt"><span class="tag good">MEMBERSHIP ACTIVE</span><h1 class="heading">You’re in. Let’s get stronger.</h1><p>Your ${result.plan.Plan_Name} membership is ready.</p><div class="table-wrap"><table><tbody><tr><th>Receipt</th><td>${result.payment.Payment_ID}</td></tr><tr><th>Subscription</th><td>${result.sub.Sub_ID}</td></tr><tr><th>Amount paid</th><td>${formatMoney(result.payment.Amount)}</td></tr><tr><th>Payment method</th><td>${result.payment.Mode}</td></tr><tr><th>Start date</th><td>${prettyDate(result.sub.Start_Date)}</td></tr><tr><th>End date</th><td>${prettyDate(result.sub.End_Date)}</td></tr><tr><th>Status</th><td>${result.sub.Status}</td></tr></tbody></table></div><div class="pill-row" style="margin-top:20px"><button class="btn" onclick="window.print()">Print receipt</button><a class="btn secondary" href="${route('member-dashboard')}">Go to dashboard</a></div></div></div>`;shell(hero('Payment complete','Receipt saved to your account.')+content)}
const memberLinks=[['Overview','member-dashboard'],['My subscription','member-subscription'],['Payments','member-payments'],['Attendance','member-attendance'],['Sessions','member-sessions'],['Profile','member-profile'],['Notifications','member-notifications']],adminLinks=[['Overview','admin-dashboard'],['Members','admin-members'],['Plans','admin-plans'],['Subscriptions','admin-subscriptions'],['Payments','admin-payments'],['Attendance','admin-attendance'],['Trainers','admin-trainers'],['Sessions','admin-sessions'],['Equipment','admin-equipment'],['Maintenance','admin-maintenance'],['Reports','admin-reports'],['Notifications','admin-notifications'],['Settings','admin-settings']];
function portal(){const admin=view.startsWith('admin-');const role=admin?'admin':'member';if(!activeUser||activeUser.role!==role){location.replace(route('signin',`&return=${encodeURIComponent(view)}`));return}if(!admin&&!member){location.replace(route('signin'));return}const current=admin?null:db.activeSubscription(member.Member_ID),rows=(items,cols)=>`<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${items.length?items.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="muted">No records to show yet.</td></tr>`}</tbody></table></div>`;let title=({ 'member-dashboard':'Overview','member-subscription':'My subscription','member-payments':'Payments','member-attendance':'Attendance','member-sessions':'Sessions','member-profile':'Profile','member-notifications':'Notifications','admin-dashboard':'Overview','admin-members':'Members','admin-plans':'Membership plans','admin-subscriptions':'Subscriptions','admin-payments':'Payments','admin-attendance':'Attendance','admin-trainers':'Trainers','admin-sessions':'Sessions','admin-equipment':'Equipment','admin-maintenance':'Maintenance log','admin-reports':'Reports','admin-notifications':'Notifications','admin-settings':'Settings'})[view]||'Overview';let content='';if(!admin){const subs=db.all().subscriptions.filter(s=>s.Member_ID===member.Member_ID).sort((a,b)=>b.Start_Date.localeCompare(a.Start_Date)),pays=db.paymentsFor(member.Member_ID),att=db.all().attendance.filter(a=>a.Member_ID===member.Member_ID),upcoming=db.all().bookings.filter(b=>b.Member_ID===member.Member_ID).map(b=>db.all().sessions.find(s=>s.Session_ID===b.Session_ID)).filter(Boolean);if(view==='member-dashboard')content=`<div class="eyebrow">Member portal</div><h1 class="heading">Good to see you, ${esc(member.Name.split(' ')[0])}.</h1><div class="kpis"><div class="card kpi"><span>Current membership</span><strong>${current?esc(planFor(current)?.Plan_Name.split(' ')[0]||'Active'):'—'}</strong><span>${current?`Ends ${prettyDate(current.End_Date)}`:'No active plan'}</span></div><div class="card kpi"><span>Days remaining</span><strong>${current?Math.max(0,Math.ceil((new Date(current.End_Date)-new Date())/864e5)):'—'}</strong><span>Keep your momentum</span></div><div class="card kpi"><span>Visits recorded</span><strong>${att.length}</strong><span>Every rep counts</span></div><div class="card kpi"><span>Next session</span><strong>${upcoming.length?'Booked':'—'}</strong><span>${upcoming.length?upcoming[0].Focus_Area:'Find a session'}</span></div></div><div class="dash-grid"><div class="card"><h3>Membership snapshot</h3><p>${current?`You’re on ${planFor(current)?.Plan_Name}. Your plan is active through ${prettyDate(current.End_Date)}.`:'Choose a plan and start building your routine.'}</p><div class="pill-row"><a class="btn" href="${route('member-attendance')}">Check in</a><a class="btn secondary" href="${route('member-sessions')}">Book session</a><a class="btn secondary" href="${route('plans')}">Renew / choose plan</a></div></div><div class="card"><h3>Recent payments</h3>${pays.slice(-3).reverse().map(p=>`<p class="small">${p.Payment_ID} · ${formatMoney(p.Amount)} · ${prettyDate(p.Paid_On)}</p>`).join('')||'<p class="muted">No payments yet.</p>'}</div></div>`;else if(view==='member-subscription')content=`<h1 class="heading">My subscription</h1><div class="pill-row" style="margin-bottom:16px"><a class="btn" href="${route('plans')}">Renew or choose plan</a></div>${rows(subs.map(s=>[s.Sub_ID,planFor(s)?.Plan_Name,prettyDate(s.Start_Date),prettyDate(s.End_Date),`<span class="tag ${s.Status==='Active'?'good':''}">${s.Status}</span>`]),['Subscription','Plan','Start','End','Status'])}`;else if(view==='member-payments')content=`<h1 class="heading">Payments & receipts</h1><button class="btn secondary" onclick="window.print()">Print this page</button><div style="height:15px"></div>${rows(pays.map(p=>[p.Payment_ID,formatMoney(p.Amount),prettyDate(p.Paid_On),p.Mode,planFor(db.all().subscriptions.find(s=>s.Sub_ID===p.Sub_ID))?.Plan_Name||'—']),['Payment','Amount','Paid on','Method','Plan'])}`;else if(view==='member-attendance'){const open=att.find(a=>a.Visit_Date===new Date().toISOString().slice(0,10)&&!a.Check_Out);content=`<h1 class="heading">Attendance</h1><div class="card"><p class="muted">${current?'Your membership is active. Show up and put in the work.':'An active membership is needed to check in.'}</p><button class="btn" data-action="${open?'checkout':'checkin'}">${open?'Check out':'Check in'}</button>${!current?` <a class="btn secondary" href="${route('plans')}">See plans</a>`:''}</div><h3 style="margin-top:28px">Visit history</h3>${rows(att.slice(0,30).map(a=>[prettyDate(a.Visit_Date),a.Check_In,a.Check_Out||'In progress',a.Check_Out?`${Math.max(0,parseInt(a.Check_Out)-parseInt(a.Check_In))} hr`: '—']),['Visit date','Check in','Check out','Duration'])}` }else if(view==='member-sessions')content=`<h1 class="heading">Sessions</h1><p class="muted">Choose a class to book. Contact the front desk to change a booking within two hours of start time.</p>${sessionsTable()}`;else if(view==='member-profile')content=`<h1 class="heading">Profile</h1><form class="card form" style="max-width:700px" data-form="profile"><div class="field-row"><div class="field"><label>Name</label><input class="input" name="Name" value="${esc(member.Name)}" required></div><div class="field"><label>Gender</label><select name="Gender">${['Male','Female','Other','Prefer not to say'].map(x=>`<option ${member.Gender===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label>Phone</label><input class="input" name="Phone" value="${esc(member.Phone)}" required></div><div class="field"><label>Email</label><input class="input" type="email" name="Email" value="${esc(member.Email)}" required></div></div><div class="field-row"><div class="field"><label>Date of birth</label><input class="input" value="${prettyDate(member.DOB)}" readonly></div><div class="field"><label>Member since</label><input class="input" value="${prettyDate(member.Join_Date)}" readonly></div></div><button class="btn">Save profile</button></form>`;else content=`<h1 class="heading">Notifications</h1><div class="notice">You’re all caught up. Important membership and booking updates will appear here.</div>`;
}else{const all=db.all(),month=new Date().getMonth(),year=new Date().getFullYear(),rev=all.payments.filter(p=>{const d=new Date(p.Paid_On);return d.getMonth()===month&&d.getFullYear()===year}).reduce((n,p)=>n+p.Amount,0),exp=all.subscriptions.filter(s=>s.Status==='Active'&&(new Date(s.End_Date)-new Date())/864e5<=7).length,due=all.equipment.filter(e=>['Needs Service','Out of Order'].includes(e.Condition)).length;if(view==='admin-dashboard')content=`<div class="eyebrow">Owner workspace</div><h1 class="heading">Operations at a glance</h1><div class="kpis"><div class="card kpi"><span>Active members</span><strong>${new Set(all.subscriptions.filter(s=>s.Status==='Active').map(s=>s.Member_ID)).size}</strong><span>Current subscriptions</span></div><div class="card kpi"><span>Revenue this month</span><strong>${formatMoney(rev)}</strong><span>Recorded payments</span></div><div class="card kpi"><span>Expiring in 7 days</span><strong>${exp}</strong><span>Renewal follow-up</span></div><div class="card kpi"><span>Equipment service due</span><strong>${due}</strong><span>Needs attention</span></div></div><div class="dash-grid"><div class="card"><h3>Revenue trend</h3><canvas id="revenue-chart" height="170"></canvas></div><div class="card"><h3>Membership mix</h3><canvas id="plan-chart" height="170"></canvas></div></div><div class="dash-grid"><div class="card"><h3>Most chosen plans</h3>${Object.entries(all.subscriptions.reduce((o,s)=>(o[planFor(s)?.Plan_Name||'Other']=(o[planFor(s)?.Plan_Name||'Other']||0)+1,o),{})).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([n,c])=>`<p>${n} <span class="tag">${c}</span></p>`).join('')}</div><div class="card"><h3>Popular goals</h3>${Object.entries(all.finderAnswers.reduce((o,a)=>(o[a.goal]=(o[a.goal]||0)+1,o),{})).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([n,c])=>`<p>${n} <span class="tag">${c}</span></p>`).join('')||'<p class="muted">Plan finder answers will appear here.</p>'}</div></div>`;else if(view==='admin-members')content=`<div class="section-head"><div><h1 class="heading">Members</h1><p class="muted">Search member records and review their subscriptions.</p></div><input class="input" style="max-width:300px" placeholder="Search name, email or ID" data-table-search></div>${rows(all.members.map(m=>[m.Member_ID,esc(m.Name),esc(m.Email),'+91 '+m.Phone,prettyDate(m.Join_Date),`<a href="${route('admin-subscriptions')}">View</a>`]),['ID','Name','Email','Phone','Joined','Action'])}`;else if(view==='admin-plans')content=`<h1 class="heading">Membership plans</h1><div class="notice">Presentation perks are managed separately from the relational plan records.</div><div style="height:16px"></div>${rows(all.plans.map(p=>[p.Plan_ID,p.Plan_Name,p.Duration_Months,formatMoney(p.Fee),formatMoney(Math.round(p.Fee/p.Duration_Months))]),['ID','Plan name','Months','Fee','Effective / month'])}`;else if(view==='admin-subscriptions')content=`<h1 class="heading">Subscriptions</h1>${rows(all.subscriptions.slice().reverse().map(s=>[s.Sub_ID,s.Member_ID,planFor(s)?.Plan_Name,prettyDate(s.Start_Date),prettyDate(s.End_Date),s.Status]),['ID','Member','Plan','Start','End','Status'])}`;else if(view==='admin-payments')content=`<h1 class="heading">Payments</h1>${rows(all.payments.slice().reverse().map(p=>[p.Payment_ID,p.Sub_ID,formatMoney(p.Amount),prettyDate(p.Paid_On),p.Mode]),['Payment','Subscription','Amount','Paid on','Method'])}`;else if(view==='admin-attendance')content=`<h1 class="heading">Attendance records</h1>${rows(all.attendance.slice(0,100).map(a=>[a.Att_ID,a.Member_ID,prettyDate(a.Visit_Date),a.Check_In,a.Check_Out||'Open']),['ID','Member','Visit date','Check in','Check out'])}`;else if(view==='admin-trainers')content=`<h1 class="heading">Trainers</h1>${rows(all.trainers.map(t=>[t.Trainer_ID,t.Name,t.Specialization,'••••••••••',formatMoney(t.Salary)]),['ID','Name','Specialization','Phone','Salary'])}`;else if(view==='admin-sessions')content=`<h1 class="heading">Sessions</h1>${sessionsTable()}`;else if(view==='admin-equipment')content=`<h1 class="heading">Equipment</h1>${rows(all.equipment.map(e=>[e.Equip_ID,e.Name,e.Category,e.Condition,prettyDate(e.Purchase_Date)]),['ID','Name','Category','Condition','Purchase date'])}`;else if(view==='admin-maintenance')content=`<h1 class="heading">Maintenance log</h1>${rows(all.maintenanceLogs.map(l=>[l.Log_ID,l.Equip_ID,prettyDate(l.Service_Date),formatMoney(l.Cost),l.Technician]),['ID','Equipment','Service date','Cost','Technician'])}`;else if(view==='admin-reports')content=`<h1 class="heading">Reports</h1><div class="grid three">${[['Subscription count',all.subscriptions.length],['Lifetime revenue',formatMoney(all.payments.reduce((n,p)=>n+p.Amount,0))],['Visits tracked',all.attendance.length]].map(([n,v])=>`<div class="card"><span class="muted">${n}</span><h2>${v}</h2></div>`).join('')}</div>`;else content=`<h1 class="heading">${title}</h1><div class="notice">${view==='admin-settings'?'Brand and seed data live in js/config.js and js/data.js.':'Recent updates and operational notices will appear here.'}</div>`}
$('#app').innerHTML=`<div class="portal"><aside class="sidebar" id="sidebar"><a class="brand" href="${route('home')}"><span class="brand-mark">S</span>Sinewforge</a><div class="side-group">${admin?'Gym operations':'My account'}</div>${(admin?adminLinks:memberLinks).map(([n,p])=>`<a class="side-link ${view===p?'active':''}" href="${route(p)}">${n}</a>`).join('')}<div class="side-group">Public</div><a class="side-link" href="${route('home')}">← Visit website</a><button class="side-link" data-action="signout" style="width:100%;border:0;background:none;text-align:left">Sign out</button></aside><div class="portal-main"><div class="portal-top"><div class="pill-row"><button class="icon-btn mobile-toggle" data-action="sidebar">☰</button><span class="muted small">${admin?'STAFF PORTAL':'MEMBER PORTAL'}</span></div><div class="pill-row"><span class="avatar">${esc((activeUser.user||'S').slice(0,1).toUpperCase())}</span><span class="small">${esc(activeUser.user)}</span></div></div><main class="portal-content">${content}</main></div></div>`;if(view==='admin-dashboard'&&window.Chart){new Chart($('#revenue-chart'),{type:'line',data:{labels:['May','Jun','Jul','Aug','Sep','Oct'],datasets:[{label:'Revenue',data:[48000,62000,58000,76000,69000,rev],borderColor:'#ff5a1f',backgroundColor:'#ff5a1f22',fill:true,tension:.35}]},options:{plugins:{legend:{display:false}},scales:{y:{ticks:{color:'#9aa3af'}},x:{ticks:{color:'#9aa3af'}}}}});new Chart($('#plan-chart'),{type:'doughnut',data:{labels:['Forge','Apex'],datasets:[{data:[all.subscriptions.filter(s=>planFor(s)?.Plan_Name.startsWith('Forge')).length,all.subscriptions.filter(s=>planFor(s)?.Plan_Name.startsWith('Apex')).length],backgroundColor:['#ff5a1f','#c6f432']}]},options:{plugins:{legend:{labels:{color:'#f4f5f7'}}}}})}}
function signout(){if(confirm('Sign out of Sinewforge Fitness?')){db.logout();location.href=route('home');setTimeout(()=>toast('You’ve been signed out.'),200)}}
function bind(){document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action==='menu')$('.navlinks')?.classList.toggle('open');if(action==='signout')signout();if(action==='sidebar')$('#sidebar')?.classList.toggle('open');if(action==='next-step'||action==='back-step'){const d=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}');d.step=Math.max(0,Math.min(3,(Number(d.step)||0)+(action==='next-step'?1:-1)));localStorage.setItem('sf-finder-draft',JSON.stringify(d));finder()}if(action==='retake'){localStorage.removeItem('sf-finder-draft');finder()}if(action==='recommend')recommend();if(action==='verify-code'){const expected=sessionStorage.getItem('sf-otp');const entered=$$('.otp input').map(x=>x.value).join('');if(entered!==expected){toast('That code did not match. Request a fresh code and try again.');return}const form=$('[data-form="signin"]'),role=$('[name="role"]',form).value,ident=$('[name="identity"]',form).value.trim(),user=role==='admin'?'owner@sinewforge.fit':ident;db.login(user,role);toast('You are signed in. Welcome to Sinewforge.');const target=params.get('return');location.href=route(target|| (role==='admin'?'admin-dashboard':'member-dashboard'),target==='purchase'?`&plan=${params.get('plan')||''}`:'')}if(action==='resend'){sendCode($('[data-form="signin"]'))}if(action==='checkin'){try{db.checkIn(member.Member_ID);toast('Checked in. Have a strong session.');portal()}catch(err){toast(err.message)}}if(action==='checkout'){try{db.checkOut(member.Member_ID);toast('Checked out. Nice work today.');portal()}catch(err){toast(err.message)}}if(action==='verify-signup'){const code=sessionStorage.getItem('sf-signup-otp'),entered=$$('.otp input').map(x=>x.value).join('');if(entered!==code){toast('That code did not match.');return}const pending=JSON.parse(sessionStorage.getItem('sf-signup')||'{}'),list=db.all().members,id=`M${String(list.length+1).padStart(3,'0')}`,m={Member_ID:id,Name:pending.name,DOB:pending.dob,Gender:pending.gender,Phone:pending.phone,Email:pending.email,Join_Date:new Date().toISOString().slice(0,10)};list.push(m);db.save();db.login(m.Email,'member');sessionStorage.removeItem('sf-signup');location.href=route('member-dashboard')}}const choice=e.target.closest('[data-choice]');if(choice){const opts=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}'),step=Number(opts.step||0),key=['training','equipment','goal'][step];opts[key]=opts[key]||[];const i=opts[key].indexOf(choice.dataset.choice);if(i>=0&&step===1)opts[key].splice(i,1);else if(i<0){if(step!==1)opts[key]=[];opts[key].push(choice.dataset.choice)}localStorage.setItem('sf-finder-draft',JSON.stringify(opts));finder()}const pf=e.target.closest('[data-plan-filter]');if(pf){$$('[data-plan-filter]').forEach(x=>x.classList.toggle('active',x===pf));$('#plan-list').innerHTML=plansGrid(Number(pf.dataset.planFilter)||null)}const filter=e.target.closest('[data-filter]');if(filter){$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===filter));$$('.trainer-card,.equipment-card').forEach(card=>{const val=card.dataset.specialty||card.dataset.category;card.classList.toggle('hide',filter.dataset.filter!=='all'&&val!==filter.dataset.filter)})}const book=e.target.closest('[data-book]');if(book){db.book(member.Member_ID,book.dataset.book);toast('Session booked. See you there.');portal()}});
document.addEventListener('input',e=>{if(e.target.matches('[data-otp]')){const inputs=$$('.otp input'),i=inputs.indexOf(e.target);e.target.value=e.target.value.replace(/\D/g,'').slice(-1);if(e.target.value&&inputs[i+1])inputs[i+1].focus()}if(e.target.matches('[data-budget]')){$('#budget-value').textContent=formatMoney(e.target.value);const d=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}');d.budget=Number(e.target.value);localStorage.setItem('sf-finder-draft',JSON.stringify(d))}if(e.target.matches('[data-table-search]')){const term=e.target.value.toLowerCase();$$('tbody tr').forEach(row=>row.classList.toggle('hide',!row.textContent.toLowerCase().includes(term)))}});document.addEventListener('keydown',e=>{if(e.target.matches('[data-otp]')&&e.key==='Backspace'&&!e.target.value){const inputs=$$('.otp input'),i=inputs.indexOf(e.target);if(inputs[i-1])inputs[i-1].focus()}if(e.target.matches('[data-otp]')&&e.key==='Enter')$('[data-action="verify-code"]')?.click()});document.addEventListener('paste',e=>{if(e.target.matches('[data-otp]')){const text=(e.clipboardData||window.clipboardData).getData('text').replace(/\D/g,'').slice(0,6);$$('.otp input').forEach((x,i)=>x.value=text[i]||'');$$('.otp input')[Math.min(text.length,5)]?.focus();e.preventDefault()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-commit]')){const d=JSON.parse(localStorage.getItem('sf-finder-draft')||'{}');d.commit=Number(e.target.value);localStorage.setItem('sf-finder-draft',JSON.stringify(d))}if(e.target.matches('[data-session-filter],[data-trainer-filter]')){const focus=$('[data-session-filter]')?.value||'all',trainer=$('[data-trainer-filter]')?.value||'all';$$('tbody tr[data-focus]').forEach(r=>r.classList.toggle('hide',(focus!=='all'&&r.dataset.focus!==focus)||(trainer!=='all'&&r.dataset.trainer!==trainer)))}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form,data=Object.fromEntries(new FormData(form));if(type==='newsletter'){toast('You’re on the list. Look out for training notes from us.');form.reset()}if(type==='ticket'){const ref=db.createTicket(data);form.reset();toast(`Request received. Your reference is ${ref}.`)}if(type==='signin')sendCode(form);if(type==='signup'){const age=(Date.now()-new Date(data.dob).getTime())/(365.25*864e5);if(age<16){toast('Members must be at least 16 years old.');return}if(!/^[6-9]\d{9}$/.test(data.phone)){toast('Enter a valid 10 digit Indian mobile number.');return}if(db.all().members.some(m=>m.Email.toLowerCase()===data.email.toLowerCase()||m.Phone===data.phone)){toast('An account already uses that phone or email. Sign in instead.');return}sessionStorage.setItem('sf-signup',JSON.stringify(data));const code=String(Math.floor(100000+Math.random()*900000));sessionStorage.setItem('sf-signup-otp',code);toast(`Your Sinewforge verification code is ${code}. It is valid for 5 minutes.`);form.innerHTML=`<h2 class="heading">Verify your details</h2><p class="muted">Enter the code sent to your phone and email.</p><div class="otp">${Array.from({length:6},(_,i)=>`<input class="input" inputmode="numeric" maxlength="1" aria-label="Code digit ${i+1}" data-otp="${i}">`).join('')}</div><button class="btn" type="button" data-action="verify-signup">Verify and create account</button>`}if(type==='purchase'){const session=db.session();if(!session){location.href=route('signin',`&return=purchase&plan=${data.planId}`);return}try{const result=db.purchase(session.memberId,data.planId,data.mode);receipt(result)}catch(err){toast(err.message)}}if(type==='profile'){const phone=data.Phone.replace(/\D/g,'').replace(/^91/,'');if(!/^[6-9]\d{9}$/.test(phone)){toast('Enter a valid 10 digit Indian mobile number.');return}db.updateMember(member.Member_ID,{...data,Phone:phone});toast('Profile updated.');portal()}});
}
function sendCode(form){const identity=$('[name="identity"]',form)?.value.trim(),role=$('[name="role"]',form)?.value;if(!identity)return;const isKnown=role==='admin'?identity.toLowerCase().endsWith('@sinewforge.fit')||identity==='owner':db.all().members.some(m=>[m.Email.toLowerCase(),m.Phone,m.Member_ID.toLowerCase()].includes(identity.toLowerCase()));if(!isKnown){toast('We couldn’t find that account. Join now to create your member profile.');return}const code=String(Math.floor(100000+Math.random()*900000));sessionStorage.setItem('sf-otp',code);sessionStorage.setItem('sf-otp-until',String(Date.now()+300000));toast(`Your Sinewforge verification code is ${code}. It is valid for 5 minutes.`);$('[data-otp-zone]',form).classList.remove('hide');$$('.otp input',form)[0].focus()}
localStorage.removeItem('sf-theme');document.documentElement.removeAttribute('data-theme');const idle=activeUser?.lastActivity;if(activeUser&&Date.now()-idle>30*60*1000){db.logout();toast('Your session expired after 30 minutes of inactivity. Please sign in again.');if(view.startsWith('member-')||view.startsWith('admin-'))location.replace(route('signin'))}else if(activeUser&&(view.startsWith('member-')||view.startsWith('admin-')))db.touch();
if(view==='home')shell(home());else if(view==='plans')plansPage();else if(view==='finder')finder();else if(view==='signin')authPage();else if(view==='signup')authPage(true);else if(view==='purchase')purchase();else if(view.startsWith('member-')||view.startsWith('admin-'))portal();else if(['about','trainers','equipment','schedule','help','privacy','terms','refund'].includes(view))infoPage(view);else shell(`${hero('Page not found','This page wandered off the training floor.')}<section class="section"><div class="wrap"><a class="btn" href="${route('home')}">Back to home</a></div></section>`);bind();
document.addEventListener('submit',e=>{if(e.target.matches('[data-form="signin"]')){sessionStorage.setItem('sf-otp-attempts','0');sessionStorage.setItem('sf-otp-cooldown',String(Date.now()+30000));sessionStorage.setItem('sf-otp-expiry',String(Date.now()+300000))}if(e.target.matches('[data-form="signup"]')){sessionStorage.setItem('sf-signup-attempts','0');sessionStorage.setItem('sf-signup-expiry',String(Date.now()+300000))}},true);
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='resend'){const until=Number(sessionStorage.getItem('sf-otp-cooldown')||0);if(Date.now()<until){e.preventDefault();e.stopImmediatePropagation();toast(`You can request another code in ${Math.ceil((until-Date.now())/1000)} seconds.`);return}sessionStorage.setItem('sf-otp-cooldown',String(Date.now()+30000));sessionStorage.setItem('sf-otp-expiry',String(Date.now()+300000));sessionStorage.setItem('sf-otp-attempts','0')}if(action==='verify-code'){const expiry=Number(sessionStorage.getItem('sf-otp-expiry')||0),locked=Number(sessionStorage.getItem('sf-otp-lock')||0),expected=sessionStorage.getItem('sf-otp'),entered=$$('.otp input').map(x=>x.value).join('');if(Date.now()<locked){e.preventDefault();e.stopImmediatePropagation();toast(`Please wait ${Math.ceil((locked-Date.now())/1000)} seconds before trying again.`);return}if(Date.now()>expiry){e.preventDefault();e.stopImmediatePropagation();toast('That code has expired. Request a new one.');return}if(entered!==expected){const attempts=Number(sessionStorage.getItem('sf-otp-attempts')||0)+1;sessionStorage.setItem('sf-otp-attempts',String(attempts));if(attempts>=3){sessionStorage.setItem('sf-otp-lock',String(Date.now()+60000));sessionStorage.setItem('sf-otp-attempts','0');toast('Three incorrect codes. Sign-in is locked for 60 seconds.')}else toast(`That code did not match. ${3-attempts} attempts remain.`);e.preventDefault();e.stopImmediatePropagation()}}if(action==='verify-signup'){const expiry=Number(sessionStorage.getItem('sf-signup-expiry')||0),expected=sessionStorage.getItem('sf-signup-otp'),entered=$$('.otp input').map(x=>x.value).join('');if(Date.now()>expiry){e.preventDefault();e.stopImmediatePropagation();toast('That code has expired. Please start sign-up again.');return}if(entered!==expected){const attempts=Number(sessionStorage.getItem('sf-signup-attempts')||0)+1;sessionStorage.setItem('sf-signup-attempts',String(attempts));toast(attempts>=3?'Three incorrect codes. Please start sign-up again.':`That code did not match. ${3-attempts} attempts remain.`);e.preventDefault();e.stopImmediatePropagation()}}},true);
document.addEventListener('click',()=>{if(db.session())db.touch()},true);document.addEventListener('input',()=>{if(db.session())db.touch()},true);
})();
